#include "editor_gizmo.hpp"
#include "editor_transform.hpp"
#include <stdexcept>
#include <iostream>
using namespace ofo;void need(bool b,const char*s){if(!b)throw std::runtime_error(s);}
int main(){PropDefinition p;p.id=7;p.center={1,2,3};p.half={1,1,1};p.transform=translate({10,0,0});TrackPlacement a{0,{10,0,0},0,7};auto origin=pivot_world(p,a,EditorPivot::BoundsCenter);need(rotate_placement_axis(p,a,{1,0,0},1.5707963268f,origin),"X rotation");need(length(pivot_world(p,a,EditorPivot::BoundsCenter)-origin)<.0001f,"pivot retained");need(length(direction(placement_matrix(p,a),{0,1,0})-Vec{0,0,1})<.0001f,"true 3D rotation applied");Geometry g;g.source="tracks/forest/forest1/geometry/track_geom.w32";g.props.push_back(p);g.materials.push_back({});Mesh m;m.name="prop";m.captured=true;m.prop_index=0;m.transform=p.transform;m.vertices.resize(3);m.vertices[1].position={1,0,0};m.vertices[2].position={0,1,0};m.indices={0,1,2};g.meshes.push_back(m);TrackDocument d;d.stage="tracks/forest/forest1/a";a.replace_native=true;d.placements={a};auto restored=parse_track_document(track_document_json(d));need(restored.placements[0].rotation==a.rotation&&restored.placements[0].replace_native,"3D transform roundtrip");apply_track_document(g,restored);need(g.props.size()==1&&g.meshes.size()==1,"native override must not clone");need(g.props[0].transform==placement_matrix(p,a),"native physics pose moved");need(g.meshes[0].transform==placement_matrix(p,a),"native visual pose moved");auto bad=restored;bad.placements.push_back(bad.placements[0]);auto before=g.props[0].transform;bool rejected=false;try{apply_track_document(g,bad);}catch(const std::exception&){rejected=true;}need(rejected&&g.props[0].transform==before,"duplicate native override rejected before mutation");TransformNumber number;need(!number.value(),"empty numeric input");number.input('2');number.input('.');number.input('5');number.input('-');need(number.value()&&*number.value()==-2.5f,"signed decimal entry");number.backspace();need(number.value()&&*number.value()==-2.f,"backspace editing");number.clear();number.input('.');need(!number.value(),"incomplete number rejected");std::cout<<"3D pivot, native override, numeric transform input passed\n";}
